/** What went wrong, in words an operator can act on. */
function providerProblemWords(record: ProviderRecoveryRecord): string {
  const last = record.submissions[record.submissions.length - 1];
  const status = last?.httpStatus;
  if (record.condition === "AUTH_FAILURE" || status === 401 || status === 403) return "the provider rejected the credentials";
  if (record.condition === "QUOTA_EXHAUSTED" || status === 402) return "the provider account is out of quota";
  if (record.condition === "RATE_LIMITED" || status === 429) return "the provider is rate limiting requests";
  if (record.condition === "OVERLOADED" || status === 503 || status === 529) return "the provider is overloaded";
  if (record.condition === "DRAINING") return "the provider is restarting";
  if (last?.kind === "timeout") return "the provider did not answer in time";
  if (last?.kind === "network_error" || record.condition === "TEMPORARILY_UNAVAILABLE") return "the provider cannot be reached";
  return "the provider returned an error";
}

function minutesWords(ms: number): string {
  const minutes = Math.round(ms / 60_000);
  return minutes < 1 ? "under a minute" : `about ${minutes} min`;
}

function rawProviderCause(record: ProviderRecoveryRecord): string {
  const last = record.submissions[record.submissions.length - 1];
  const parts = [
    `condition ${record.condition}${last?.httpStatus ? `, HTTP ${last.httpStatus}` : ""}${last ? `, ${last.kind}, execution ${last.execution}` : ""}`,
    last?.message,
    record.reason ? `recovery: ${record.reason}` : undefined,
    last?.requestId ? `request ${last.requestId}` : undefined,
  ];
  return redactSecrets(scrubUrls(parts.filter(Boolean).join("\n")));
}

/**
 * The provider-wait status line for one recovery transition (PROBING produces none). Every transition carries the
 * same `key`, so the client shows one row that changes instead of a line per attempt (D-06).
  onFailure?(failure: InferenceFailure): void;
  /**
   * Asked before waiting in place on a NOT_EXECUTED failure (never on UNKNOWN). True ends recovery as YIELDED
   * and rethrows, so a scheduler can reroute or park the work instead of this step waiting on one resource.
   */
  shouldYield?(failure: InferenceFailure, plannedDelayMs: number): boolean;
}

export interface RecoveryControllerOptions {
  /** False when the endpoint has never succeeded in this session; bounds waiting to `firstContactDeadlineMs` (REQ-TUI-105). */
  everSucceeded?: boolean;
  endpoint?: string;
}

/** Startup probe diagnosis (REQ-TUI-105): names the endpoint URL, cause, and fix when unreachable or rejected. */
export function startupEndpointWarning(endpoint: string, probe: ProbeResult): string | undefined {
  const problem = startupEndpointProblem(endpoint, probe);
  return problem ? startupProblemWarning(problem) : undefined;
}

export function startupProblemWarning(problem: StartupEndpointProblem): string {
  return problem.kind === "unreachable"
    ? `Endpoint ${problem.endpoint} is unreachable${problem.detail ? ` (${problem.detail})` : ""}. Run \`nexus doctor\`, check LOCAL_LLM_ENDPOINT in ~/.config/nexus/config.env, or use /connect.`
    : `Endpoint ${problem.endpoint} rejected credentials (${problem.detail}). Run \`nexus doctor\`, check ~/.config/nexus/config.env, or use /connect.`;
}

/** Why no model can be used right now, as the start-up probe found it (D-07). `detail` is the raw cause, for inspection only. */
export interface StartupEndpointProblem {
  kind: "unreachable" | "rejected";
  endpoint: string;
  detail: string;
  /**
   * True only when the connection itself failed (refused, DNS, TLS, reset): a prompt cannot work. A timeout, an HTTP
   * error from /models (503 while a model loads, 429) or a rejection says nothing about the chat path.
   */
  blocking: boolean;
  /** The connection was refused or the host did not resolve: nothing is listening there (otherwise something answered badly). */
  nothingThere: boolean;
}

export function startupEndpointProblem(endpoint: string, probe: ProbeResult): StartupEndpointProblem | undefined {
  if (!probe.available) {
    const detail = scrubUrls(probe.detail ?? "");
    const blocking = probe.httpStatus === undefined && !probe.timedOut;
    const nothingThere = /ECONNREFUSED|ENOTFOUND|EAI_AGAIN|bad port/i.test(detail);
    return { kind: "unreachable", endpoint: persistableEndpoint(endpoint), detail, blocking, nothingThere };
  }
  if (probe.httpStatus === 401 || probe.httpStatus === 403) {
    return { kind: "rejected", endpoint: persistableEndpoint(endpoint), detail: `HTTP ${probe.httpStatus}`, blocking: false, nothingThere: false };
  }
  return undefined;
}

